  ::obe::cli::usage_para options::
  print_usage (::std::ostream& os, ::obe::cli::usage_para p)
  {
    CLI_POTENTIALLY_UNUSED (os);

    if (p != ::obe::cli::usage_para::none)
      os << ::std::endl;

    os << "\033[1mOPTIONS\033[0m" << ::std::endl;

    os << std::endl
       << "\033[1m--help\033[0m                          Print usage information and exit." << ::std::endl;

    os << std::endl
       << "\033[1m--version\033[0m                       Print version and exit." << ::std::endl;

    os << std::endl
       << "\033[1m--options-file\033[0m \033[4mfile\033[0m             Read additional options from \033[4mfile\033[0m. Each option" << ::std::endl
       << "                                should appear on a separate line optionally" << ::std::endl
       << "                                followed by space or equal sign (\033[1m=\033[0m) and an" << ::std::endl
       << "                                option value. Empty lines and lines starting" << ::std::endl
       << "                                with \033[1m#\033[0m are ignored." << ::std::endl;

    os << std::endl
       << "\033[1m-v\033[0m                              Print informational messages, such as the" << ::std::endl
       << "                                listening endpoints. This is equivalent to" << ::std::endl
       << "                                \033[1m--verbose 2\033[0m." << ::std::endl;

    os << std::endl
       << "\033[1m-V\033[0m                              Print trace messages, such as where the stored" << ::std::endl
       << "                                files are kept. This is equivalent to \033[1m--verbose" << ::std::endl
       << "                                3\033[0m." << ::std::endl;

    os << std::endl
       << "\033[1m--quiet\033[0m|\033[1m-q\033[0m                      Print errors only. This is equivalent to" << ::std::endl
       << "                                \033[1m--verbose 0\033[0m." << ::std::endl;

    os << std::endl
       << "\033[1m--verbose\033[0m \033[4mlevel\033[0m                 Set the diagnostics verbosity to \033[4mlevel\033[0m between" << ::std::endl
       << "                                0 and 3. Level 0 prints errors only, level 1" << ::std::endl
       << "                                (the default) also warnings, level 2 also" << ::std::endl
       << "                                informational messages, and level 3 also trace" << ::std::endl
       << "                                messages. Note that the diagnostics of the" << ::std::endl
       << "                                servers themselves (for example, the failed" << ::std::endl
       << "                                gateway tasks) are currently printed regardless" << ::std::endl
       << "                                of the verbosity." << ::std::endl;

    os << std::endl
       << "\033[1m--auth-address\033[0m \033[4maddr\033[0m             Listen for the authentication requests on \033[4maddr\033[0m." << ::std::endl
       << "                                The default is all IPv4 interfaces." << ::std::endl;

    os << std::endl
       << "\033[1m--auth-port\033[0m \033[4mport\033[0m                Listen for the authentication requests on \033[4mport\033[0m." << ::std::endl
       << "                                The default is 443. If \033[4mport\033[0m is 0, then the" << ::std::endl
       << "                                system chooses a free port (see" << ::std::endl
       << "                                \033[1m--print-endpoints\033[0m)." << ::std::endl;

    os << std::endl
       << "\033[1m--lsg-address\033[0m \033[4maddr\033[0m              Listen for the lobby service gateway" << ::std::endl
       << "                                connections on \033[4maddr\033[0m. The default is all IPv4" << ::std::endl
       << "                                interfaces." << ::std::endl;

    os << std::endl
       << "\033[1m--lsg-port\033[0m \033[4mport\033[0m                 Listen for the lobby service gateway" << ::std::endl
       << "                                connections on \033[4mport\033[0m. The default is 3074. If" << ::std::endl
       << "                                \033[4mport\033[0m is 0, then the system chooses a free port" << ::std::endl
       << "                                (see \033[1m--print-endpoints\033[0m)." << ::std::endl;

    os << std::endl
       << "\033[1m--bandwidth-address\033[0m \033[4maddr\033[0m        Receive the bandwidth test packets on \033[4maddr\033[0m. The" << ::std::endl
       << "                                default is all IPv4 interfaces." << ::std::endl;

    os << std::endl
       << "\033[1m--bandwidth-port\033[0m \033[4mport\033[0m           Receive the bandwidth test packets on UDP \033[4mport\033[0m." << ::std::endl
       << "                                The default is 3075. If \033[4mport\033[0m is 0, then the" << ::std::endl
       << "                                system chooses a free port (see" << ::std::endl
       << "                                \033[1m--print-endpoints\033[0m)." << ::std::endl;

    os << std::endl
       << "\033[1m--bandwidth-public-address\033[0m \033[4maddr\033[0m The IPv4 address the clients send the bandwidth" << ::std::endl
       << "                                test packets to. If unspecified, it is the" << ::std::endl
       << "                                address the client reached the gateway at," << ::std::endl
       << "                                which is only right if the bandwidth test" << ::std::endl
       << "                                packets are received on that address too and" << ::std::endl
       << "                                the client can reach it directly (rather than" << ::std::endl
       << "                                through NAT or a proxy). Note that without an" << ::std::endl
       << "                                IPv4 address the clients cannot test their" << ::std::endl
       << "                                bandwidth, in which case they assume they have" << ::std::endl
       << "                                enough." << ::std::endl;

    os << std::endl
       << "\033[1m--bandwidth-public-port\033[0m \033[4mport\033[0m    The UDP port the clients send the bandwidth" << ::std::endl
       << "                                test packets to. If unspecified, it is the port" << ::std::endl
       << "                                they are received on (see \033[1m--bandwidth-port\033[0m)." << ::std::endl;

    os << std::endl
       << "\033[1m--tls-certificate\033[0m \033[4mfile\033[0m          The authentication server certificate chain in" << ::std::endl
       << "                                the PEM format. Required." << ::std::endl;

    os << std::endl
       << "\033[1m--tls-key\033[0m \033[4mfile\033[0m                  The authentication server private key in the" << ::std::endl
       << "                                PEM format. Required." << ::std::endl;

    os << std::endl
       << "\033[1m--ticket-key\033[0m \033[4mfile\033[0m               Read the server ticket sealing key (32 raw" << ::std::endl
       << "                                bytes) from \033[4mfile\033[0m. If unspecified, a random key" << ::std::endl
       << "                                is generated on startup, which means the" << ::std::endl
       << "                                tickets issued before a restart are no longer" << ::std::endl
       << "                                accepted (the clients authenticate again)." << ::std::endl;

    os << std::endl
       << "\033[1m--title\033[0m \033[4mid\033[0m                      Serve the title \033[4mid\033[0m. Repeat this option to serve" << ::std::endl
       << "                                several titles. If unspecified, any title is" << ::std::endl
       << "                                served." << ::std::endl;

    os << std::endl
       << "\033[1m--ticket-lifetime\033[0m \033[4msec\033[0m           The time the client has to connect to the" << ::std::endl
       << "                                gateway after authenticating. The default is" << ::std::endl
       << "                                3600 seconds." << ::std::endl;

    os << std::endl
       << "\033[1m--sandbox\033[0m \033[4mname\033[0m                  The sandbox name reported to the clients. The" << ::std::endl
       << "                                default is \033[1mRETAIL\033[0m." << ::std::endl;

    os << std::endl
       << "\033[1m--platform\033[0m \033[4mname\033[0m                 The device platform info reported to the" << ::std::endl
       << "                                clients. The default is \033[1mPC\033[0m." << ::std::endl;

    os << std::endl
       << "\033[1m--publisher-files\033[0m \033[4mdir\033[0m           Publish the files in the subdirectories of \033[4mdir\033[0m" << ::std::endl
       << "                                as the publisher files of the titles that the" << ::std::endl
       << "                                subdirectories are named after. The clients of" << ::std::endl
       << "                                the title can list and download these files," << ::std::endl
       << "                                for example, IW4x (title 2010) downloads its" << ::std::endl
       << "                                playlists from \033[1m2010/playlists.patch2\033[0m. The \033[1mobe\033[0m" << ::std::endl
       << "                                package installs the IW4x files into the" << ::std::endl
       << "                                \033[1mpublisher/\033[0m subdirectory of its data directory" << ::std::endl
       << "                                (for example, \033[1m/usr/share/obe/publisher/\033[0m)." << ::std::endl
       << ::std::endl
       << "                                The files are published on startup, replacing" << ::std::endl
       << "                                the contents of the publisher files with the" << ::std::endl
       << "                                same names. Note that a file that is removed" << ::std::endl
       << "                                from \033[4mdir\033[0m stays published." << ::std::endl;

    os << std::endl
       << "\033[1m--print-endpoints\033[0m               Print the authentication, gateway, and" << ::std::endl
       << "                                bandwidth test endpoints to \033[1mstdout\033[0m, one per" << ::std::endl
       << "                                line, once listening. This is primarily useful" << ::std::endl
       << "                                together with port 0, which makes the system" << ::std::endl
       << "                                choose a free port." << ::std::endl;

    os << std::endl
       << "\033[1m--db-name\033[0m \033[4mname\033[0m                  Keep the stored files and performance values in" << ::std::endl
       << "                                the PostgreSQL database \033[4mname\033[0m. If unspecified," << ::std::endl
       << "                                they are kept in memory and are lost on exit," << ::std::endl
       << "                                which is only suitable for development. The" << ::std::endl
       << "                                database schema must be created or migrated" << ::std::endl
       << "                                with \033[1m--migrate\033[0m beforehand." << ::std::endl;

    os << std::endl
       << "\033[1m--db-user\033[0m \033[4muser\033[0m                  The PostgreSQL database user. If unspecified," << ::std::endl
       << "                                the user name of the process is used." << ::std::endl;

    os << std::endl
       << "\033[1m--db-password\033[0m \033[4mpass\033[0m              The PostgreSQL database password. Note that the" << ::std::endl
       << "                                command line is visible to other users, so" << ::std::endl
       << "                                consider specifying it in an options file (see" << ::std::endl
       << "                                \033[1m--options-file\033[0m) or in the PostgreSQL password" << ::std::endl
       << "                                file (see the \033[1mPGPASSFILE\033[0m environment variable)." << ::std::endl
       << "                                If unspecified, no password is sent." << ::std::endl;

    os << std::endl
       << "\033[1m--db-host\033[0m \033[4mhost\033[0m                  The PostgreSQL database host name, address, or" << ::std::endl
       << "                                UNIX-domain socket directory. If unspecified," << ::std::endl
       << "                                the \033[1mPGHOST\033[0m environment variable is used and," << ::std::endl
       << "                                without it, the socket in \033[1m/tmp\033[0m. A local server" << ::std::endl
       << "                                normally has its socket elsewhere" << ::std::endl
       << "                                (\033[1m/var/run/postgresql\033[0m on Fedora and Debian), so" << ::std::endl
       << "                                it is reached with its socket directory, for" << ::std::endl
       << "                                example, \033[1m--db-host /var/run/postgresql\033[0m." << ::std::endl;

    os << std::endl
       << "\033[1m--db-port\033[0m \033[4mport\033[0m                  The PostgreSQL database port. If unspecified," << ::std::endl
       << "                                the default port is used." << ::std::endl;

    os << std::endl
       << "\033[1m--db-max-connections\033[0m \033[4mnum\033[0m        The most concurrent PostgreSQL database" << ::std::endl
       << "                                connections, which is also the number of" << ::std::endl
       << "                                threads that perform the database operations." << ::std::endl
       << "                                The default is 5." << ::std::endl;

    os << std::endl
       << "\033[1m--db-retry\033[0m \033[4mnum\033[0m                  Retry a database operation that fails with a" << ::std::endl
       << "                                recoverable error (for example, a serialization" << ::std::endl
       << "                                failure due to a concurrent update or a lost" << ::std::endl
       << "                                connection) up to \033[4mnum\033[0m times. The default is 10." << ::std::endl;

    os << std::endl
       << "\033[1m--migrate\033[0m                       Create the PostgreSQL database schema if there" << ::std::endl
       << "                                is none or migrate it to the current version," << ::std::endl
       << "                                then exit. Several servers may share the" << ::std::endl
       << "                                database, in which case the schema should be" << ::std::endl
       << "                                migrated once, before starting the servers of" << ::std::endl
       << "                                the new version. Requires \033[1m--db-name\033[0m." << ::std::endl;

    os << std::endl
       << "\033[1m--insecure-authentication\033[0m       Accept any platform token without verifying it," << ::std::endl
       << "                                deriving the user identity from the token" << ::std::endl
       << "                                itself. Anyone presenting the same token is the" << ::std::endl
       << "                                same user, so this is only suitable for" << ::std::endl
       << "                                development." << ::std::endl;

    p = ::obe::cli::usage_para::option;

    return p;
  }

